/**
 * Native modal dialog: Escape cancels, focus is trapped by the browser, and closing returns focus to the
 * element that opened it. Rendered only while open, so mounting shows it and unmounting closes it.
 */
export function ConfirmDialog({ title, children, confirmLabel, cancelLabel = 'Cancel', destructive = false, pending = false, onConfirm, onCancel }: Props) {
  const ref = useRef<HTMLDialogElement>(null)
  const cancelRef = useRef<HTMLButtonElement>(null)
  const confirmRef = useRef<HTMLButtonElement>(null)
  const latest = useRef(onCancel)
  useEffect(() => { latest.current = onCancel })
  useEffect(() => {
    const dialog = ref.current
    if (!dialog) return
    if (!dialog.open) dialog.showModal()
    ;(destructive ? cancelRef : confirmRef).current?.focus()
    const onNativeCancel = (event: Event) => { event.preventDefault(); latest.current() }
    dialog.addEventListener('cancel', onNativeCancel)
    return () => { dialog.removeEventListener('cancel', onNativeCancel); if (dialog.open) dialog.close() }
  }, [destructive])
  return (
    <dialog ref={ref} className="confirm-dialog" aria-labelledby="confirm-title" aria-describedby="confirm-description">
      <form method="dialog" onSubmit={event => { event.preventDefault(); if (!pending) onConfirm() }}>
