    await mkdir(join(root, 'pi', 'empty'))
    const app = createApp(root)
    try {
      const file = await mutate(app, { op: 'rename', source: 'Pi', path: 'skills/review.md', destinationPath: 'skills/Reviewed.MD' })
      assert.equal(file.statusCode, 200, file.body)
      assert.deepEqual(file.json(), { op: 'rename', source: 'Pi', path: 'skills/review.md', destinationSource: 'Pi', destinationPath: 'skills/Reviewed.MD' })
      assert.equal(await readFile(join(root, 'pi', 'skills', 'Reviewed.MD'), 'utf8'), 'review')
      assert.equal((await stat(join(root, 'pi', 'skills', 'Reviewed.MD'))).mode & 0o777, 0o640)

      const folder = await mutate(app, { op: 'rename', source: 'Pi', path: 'empty', destinationPath: 'renamed' })
      assert.equal(folder.statusCode, 200, folder.body)
      assert.deepEqual(await tree(join(root, 'pi')), ['renamed/', 'skills/', 'skills/Reviewed.MD'])

      // Different parent is a move, not a rename.
      const elsewhere = await mutate(app, { op: 'rename', source: 'Pi', path: 'skills/Reviewed.MD', destinationPath: 'Reviewed.MD' })
      assert.equal(elsewhere.statusCode, 400)
      assert.equal(elsewhere.json().code, 'INVALID_PATH')
      // A file must keep a Markdown extension; a folder must not take one.
      const extension = await mutate(app, { op: 'rename', source: 'Pi', path: 'skills/Reviewed.MD', destinationPath: 'skills/Reviewed.txt' })
      assert.equal(extension.statusCode, 400)
