        ['rename missing', { op: 'rename', source: 'Pi', path: 'missing.md', destinationPath: 'x.md' }],
        ['move missing folder', { op: 'move', source: 'Pi', path: 'missing', destinationPath: 'x' }],
        ['copy missing', { op: 'copy', source: 'Pi', path: 'missing.md', destinationSource: 'Claude', destinationPath: 'x.md' }],
        ['delete symlinked file', { op: 'delete', source: 'Pi', path: 'linked.md' }],
        ['rename symlinked file', { op: 'rename', source: 'Pi', path: 'linked.md', destinationPath: 'renamed.md' }],
