        ['create through self link', { op: 'create-folder', source: 'Pi', path: 'self/new' }],
        ['delete through symlinked dir', { op: 'delete', source: 'Pi', path: 'linked-dir/secret.md' }],
        ['move into symlinked dir', { op: 'move', source: 'Pi', path: 'real.md', destinationPath: 'linked-dir/real.md' }],
        ['move into self link', { op: 'move', source: 'Pi', path: 'real.md', destinationPath: 'self/real.md' }],
        ['copy into symlinked source root', { op: 'copy', source: 'Pi', path: 'real.md', destinationSource: 'Claude', destinationPath: 'real.md' }],
        ['create in symlinked source root', { op: 'create-file', source: 'Claude', path: 'new.md' }],
        ['delete in symlinked source root', { op: 'delete', source: 'Claude', path: 'secret.md' }],
        ['delete file as folder parent', { op: 'delete', source: 'Pi', path: 'real.md/child.md' }],
      ]
      for (const [label, payload] of cases) {
        const response = await mutate(app, payload)
